INSERT INTO question (id, question, subtopic_id, difficulty, question_type) VALUES
  ('d0000000-0000-0000-0000-000000000901', 'Which of the following numbers is an irrational number?', 'c0000009-0001-0000-0000-000000000065', 'Easy', 'MCQ'),
