  ('d0000000-0000-0000-0000-000000000909', 'If (sqrt(5) + sqrt(3)) / (sqrt(5) - sqrt(3)) = a + b*sqrt(15), find the respective values of a and b.', 'c0000009-0001-0000-0000-000000000065', 'Hard', 'MCQ'),
