  ('d0000000-0000-0000-0000-000000000916', 'Using the Remainder Theorem, find the remainder when p(x) = x^4 - 3x^2 + 2x + 1 is divided by (x - 1).', 'c0000009-0001-0000-0000-000000000066', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000000917', 'Factorize completely by splitting the middle term: 12x^2 - 7x + 1.', 'c0000009-0001-0000-0000-000000000066', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000000918', 'If (x + 2) is a factor of the cubic polynomial x^3 + 3x^2 - 2ax + 8, find the value of the constant a.', 'c0000009-0001-0000-0000-000000000066', 'Hard', 'MCQ'),
  ('d0000000-0000-0000-0000-000000000919', 'Expand using the standard trinomial square identity: (2x - y + z)^2.', 'c0000009-0001-0000-0000-000000000066', 'Medium', 'MCQ'),
  ('d0000000-0000-0000-0000-000000000920', 'If x + y + z = 0, what is the exact algebraic value of (x^3 + y^3 + z^3) / (xyz)?', 'c0000009-0001-0000-0000-000000000066', 'Hard', 'MCQ'),
